"""Value objects shared by barge-in decision logic."""

from __future__ import annotations

from typing import Any, Optional

from pydantic import BaseModel, ConfigDict


class BargeInVerdict(BaseModel):
    """The outcome of a barge-in decision.

    Attributes:
        accepted: Whether the transcript should interrupt bot playback.
        reason: A short token describing why the verdict was accepted or rejected.
        description: A human-readable explanation of the verdict, shown as-is in
            the Inspector.
        metadata: Additional detector-specific decision data.
    """

    model_config = ConfigDict(frozen=True)

    accepted: bool
    reason: Optional[str] = None
    description: Optional[str] = None
    metadata: Optional[dict[str, Any]] = None
